using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Mvc;using TransPort.Api.Controllers;using TransPort.Api.Modules.Maquinaria.DTOs;using TransPort.Api.Modules.Maquinaria.Repositories;
namespace TransPort.Api.Tests;
public sealed class MaquinariasControllerTests
{
 [Fact]public async Task Listar_PropagaAlcance(){var r=new F();await C(r,7,"Empleado").Listar(null,null,null,default);Assert.Equal(new AlcanceMaquinaria(7,false),r.A);}[Fact]public async Task Crear_RetornaId(){var r=new F{Id=5};var x=Assert.IsType<OkObjectResult>(await C(r,1,"AdministradorGeneral").Crear(new(){SedeId=1,Codigo="EQ-1",Tipo="Excavadora",Marca="X",Modelo="Y",TarifaDiaria=1},default));Assert.Equal(5,Assert.IsType<ResultadoMaquinariaDto>(x.Value).Id);}[Fact]public async Task Obtener_Inexistente_NotFound()=>Assert.IsType<NotFoundResult>(await C(new F(),1,"AdministradorGeneral").Obtener(99,default));[Fact]public async Task EstadoContrato_PropagaAlcance(){var r=new F();Assert.IsType<NoContentResult>(await C(r,3,"Operativo").EstadoContrato(1,new(){Estado="Activo"},default));Assert.Equal(new AlcanceMaquinaria(3,false),r.A);}[Fact]public void ExcluyeCliente(){var a=typeof(MaquinariasController).GetCustomAttributes(typeof(AuthorizeAttribute),true).Cast<AuthorizeAttribute>().Single();Assert.DoesNotContain("Cliente",a.Roles??"");}
 private static MaquinariasController C(IMaquinariaRepository r,int id,params string[]roles){var cs=new List<Claim>{new(ClaimTypes.NameIdentifier,id.ToString())};cs.AddRange(roles.Select(x=>new Claim(ClaimTypes.Role,x)));return new(r){ControllerContext=new(){HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity(cs,"T"))}}};}private sealed class F:IMaquinariaRepository{public int Id{get;init;}public AlcanceMaquinaria?A{get;private set;}public Task<IReadOnlyList<MaquinariaEquipoDto>>ListarAsync(string?e,int?s,string?b,AlcanceMaquinaria a,CancellationToken ct){A=a;return Task.FromResult<IReadOnlyList<MaquinariaEquipoDto>>([]);}public Task<MaquinariaDetalleDto?>ObtenerAsync(int id,AlcanceMaquinaria a,CancellationToken ct)=>Task.FromResult<MaquinariaDetalleDto?>(null);public Task<MaquinariaOpcionesDto>OpcionesAsync(AlcanceMaquinaria a,CancellationToken ct)=>Task.FromResult(new MaquinariaOpcionesDto([],[]));public Task<int>CrearEquipoAsync(CrearMaquinariaRequest x,AlcanceMaquinaria a,CancellationToken ct){A=a;return Task.FromResult(Id);}public Task<long>CrearContratoAsync(CrearContratoMaquinariaRequest x,AlcanceMaquinaria a,CancellationToken ct)=>Task.FromResult(1L);public Task<bool>EstadoContratoAsync(long id,EstadoContratoMaquinariaRequest x,AlcanceMaquinaria a,CancellationToken ct){A=a;return Task.FromResult(true);}public Task<long>CrearMantenimientoAsync(CrearMantenimientoMaquinariaRequest x,AlcanceMaquinaria a,CancellationToken ct)=>Task.FromResult(1L);public Task<bool>EstadoMantenimientoAsync(long id,EstadoMantenimientoMaquinariaRequest x,AlcanceMaquinaria a,CancellationToken ct)=>Task.FromResult(true);public Task<bool>EliminarEquipoAsync(int id,int u,CancellationToken ct)=>Task.FromResult(true);}}
